package com.governai.audit;import tools.jackson.databind.JsonNode;import java.time.OffsetDateTime;import java.util.UUID;public record AuditEventResponse(UUID id,UUID organizationId,UUID decisionRequestId,UUID actorId,String eventType,String entityType,UUID entityId,JsonNode previousState,JsonNode newState,JsonNode eventMetadata,OffsetDateTime createdAt){public static AuditEventResponse from(AuditEvent e){return new AuditEventResponse(e.getId(),e.getOrganizationId(),e.getDecisionRequestId(),e.getActorId(),e.getEventType(),e.getEntityType(),e.getEntityId(),e.getPreviousState(),e.getNewState(),e.getEventMetadata(),e.getCreatedAt());}}
